//! Integration tests for the knowledge library infrastructure\n//!\n//! These tests validate the performance targets, concurrent access patterns,\n//! AI integration, error recovery, and overall system reliability.\n\nuse std::sync::Arc;\nuse std::time::{Duration, Instant};\nuse std::collections::HashMap;\nuse tokio::time::timeout;\nuse uveddi::ai::knowledge::*;\nuse uveddi::analysis::ArchitecturalIssue;\n\n/// Test the core loading performance meets targets\n#[tokio::test]\nasync fn test_loading_performance_targets() {\n    let config = LoaderConfig::default();\n    let loader = KnowledgeLibraryLoader::new(config);\n    \n    let start_time = Instant::now();\n    let result = loader.load_knowledge_library().await;\n    let load_duration = start_time.elapsed();\n    \n    // Validate loading succeeds\n    assert!(result.is_ok(), \"Loading should succeed\");\n    \n    // Validate performance target: <100ms\n    assert!(\n        load_duration.as_millis() < 100,\n        \"Loading took {}ms, should be <100ms\",\n        load_duration.as_millis()\n    );\n    \n    println!(\"✅ Loading performance: {}ms (target: <100ms)\", load_duration.as_millis());\n}\n\n/// Test lookup performance meets targets\n#[tokio::test]\nasync fn test_lookup_performance_targets() {\n    // Initialize knowledge library\n    let loader = KnowledgeLibraryLoader::embedded();\n    let lookup = loader.load_knowledge_library().await.unwrap();\n    \n    // Test multiple lookups to get accurate timing\n    let mut total_duration = Duration::new(0, 0);\n    let test_patterns = vec![\"god_object\", \"magic_numbers\"];\n    let iterations = 100;\n    \n    for _ in 0..iterations {\n        for pattern_id in &test_patterns {\n            let start_time = Instant::now();\n            let _result = lookup.get_pattern(pattern_id);\n            total_duration += start_time.elapsed();\n        }\n    }\n    \n    let average_duration = total_duration / (iterations * test_patterns.len() as u32);\n    \n    // Validate performance target: <1ms average\n    assert!(\n        average_duration.as_micros() < 1000,\n        \"Average lookup took {}μs, should be <1000μs\",\n        average_duration.as_micros()\n    );\n    \n    println!(\"✅ Lookup performance: {}μs (target: <1000μs)\", average_duration.as_micros());\n}\n\n/// Test memory usage meets targets\n#[tokio::test]\nasync fn test_memory_usage_targets() {\n    let config = LoaderConfig {\n        max_memory_usage: 100 * 1024 * 1024, // 100MB limit\n        ..LoaderConfig::default()\n    };\n    \n    let loader = KnowledgeLibraryLoader::new(config);\n    let lookup = loader.load_knowledge_library().await.unwrap();\n    \n    // Get memory metrics from the loader\n    let memory_usage = loader.memory_manager.current_usage();\n    let memory_usage_mb = memory_usage / (1024 * 1024);\n    \n    // Validate memory target: <100MB\n    assert!(\n        memory_usage_mb < 100,\n        \"Memory usage is {}MB, should be <100MB\",\n        memory_usage_mb\n    );\n    \n    println!(\"✅ Memory usage: {}MB (target: <100MB)\", memory_usage_mb);\n}\n\n/// Test concurrent access performance and safety\n#[tokio::test]\nasync fn test_concurrent_access_performance() {\n    // Initialize knowledge library\n    let loader = KnowledgeLibraryLoader::embedded();\n    let lookup = Arc::new(loader.load_knowledge_library().await.unwrap());\n    \n    // Create performance metrics\n    let performance_metrics = Arc::new(PerformanceMetrics::new());\n    \n    // Create concurrent access system\n    let concurrent_access = Arc::new(ConcurrentKnowledgeAccess::new(\n        lookup,\n        performance_metrics,\n        1000,  // cache size\n        50,    // max concurrent readers\n    ));\n    \n    // Test concurrent operations\n    let num_tasks = 20;\n    let operations_per_task = 50;\n    \n    let start_time = Instant::now();\n    \n    let mut handles = Vec::new();\n    \n    for task_id in 0..num_tasks {\n        let access = Arc::clone(&concurrent_access);\n        let handle = tokio::spawn(async move {\n            let mut successful_ops = 0;\n            \n            for op_id in 0..operations_per_task {\n                let pattern_id = if op_id % 2 == 0 { \"god_object\" } else { \"magic_numbers\" };\n                \n                match access.get_pattern_concurrent(pattern_id).await {\n                    Ok(_) => successful_ops += 1,\n                    Err(e) => eprintln!(\"Task {} operation {} failed: {}\", task_id, op_id, e),\n                }\n            }\n            \n            successful_ops\n        });\n        \n        handles.push(handle);\n    }\n    \n    // Wait for all tasks to complete\n    let results = futures::future::join_all(handles).await;\n    let total_duration = start_time.elapsed();\n    \n    // Calculate metrics\n    let total_operations: usize = results.iter().map(|r| r.unwrap()).sum();\n    let throughput = total_operations as f64 / total_duration.as_secs_f64();\n    \n    // Validate performance target: >1000 ops/second\n    assert!(\n        throughput > 1000.0,\n        \"Throughput was {:.2} ops/sec, should be >1000 ops/sec\",\n        throughput\n    );\n    \n    // Validate all operations succeeded\n    assert_eq!(total_operations, num_tasks * operations_per_task, \"All operations should succeed\");\n    \n    // Get access statistics\n    let stats = concurrent_access.get_access_statistics();\n    println!(\"✅ Concurrent access throughput: {:.2} ops/sec (target: >1000 ops/sec)\", throughput);\n    println!(\"   Cache hit rate: {:.2}%\", stats.cache_hit_rate * 100.0);\n    println!(\"   Success rate: {:.2}%\", stats.success_rate * 100.0);\n}\n\n/// Test AI integration performance and functionality\n#[tokio::test]\nasync fn test_ai_integration_performance() {\n    // Initialize knowledge library\n    let loader = KnowledgeLibraryLoader::embedded();\n    let lookup = Arc::new(loader.load_knowledge_library().await.unwrap());\n    let performance_metrics = Arc::new(PerformanceMetrics::new());\n    \n    // Create concurrent access and AI integration\n    let concurrent_access = Arc::new(ConcurrentKnowledgeAccess::new(\n        lookup, performance_metrics, 1000, 50\n    ));\n    \n    let ai_integration = AIKnowledgeIntegration::new(\n        concurrent_access,\n        4000, // token budget\n    );\n    \n    // Create a test architectural issue\n    let test_issue = ArchitecturalIssue {\n        id: \"test_issue_1\".to_string(),\n        description: \"Large class with too many responsibilities detected\".to_string(),\n        file_path: \"src/large_class.rs\".to_string(),\n        line_number: Some(1),\n        severity: crate::analysis::Severity::High,\n        category: \"Object-Oriented\".to_string(),\n        suggested_fix: Some(\"Consider extracting smaller classes\".to_string()),\n        confidence: 0.9,\n        metadata: HashMap::new(),\n    };\n    \n    // Create context requirements\n    let context_requirements = ContextRequirements {\n        max_tokens: 2000,\n        required_patterns: vec![\"god_object\".to_string()],\n        optional_patterns: vec![\"magic_numbers\".to_string()],\n        target_language: Some(SourceLanguage::Rust),\n        include_examples: true,\n        include_solutions: true,\n        include_related: true,\n        min_confidence: 0.8,\n        optimization_level: integration::OptimizationLevel::Advanced,\n    };\n    \n    // Test prompt building performance\n    let start_time = Instant::now();\n    let enhanced_prompt = ai_integration\n        .build_enhanced_prompt(&test_issue, &context_requirements)\n        .await;\n    let duration = start_time.elapsed();\n    \n    // Validate success\n    assert!(enhanced_prompt.is_ok(), \"AI integration should succeed\");\n    \n    let prompt = enhanced_prompt.unwrap();\n    \n    // Validate performance: should be fast\n    assert!(\n        duration.as_millis() < 100,\n        \"AI integration took {}ms, should be <100ms\",\n        duration.as_millis()\n    );\n    \n    // Validate prompt quality\n    assert!(!prompt.base_prompt.is_empty(), \"Prompt should not be empty\");\n    assert!(!prompt.knowledge_context.is_empty(), \"Context should not be empty\");\n    assert!(prompt.confidence_score > 0.5, \"Confidence should be reasonable\");\n    assert!(prompt.token_count > 0, \"Token count should be calculated\");\n    \n    println!(\"✅ AI integration performance: {}ms (target: <100ms)\", duration.as_millis());\n    println!(\"   Prompt confidence: {:.2}\", prompt.confidence_score);\n    println!(\"   Token count: {}\", prompt.token_count);\n    println!(\"   Patterns included: {}\", prompt.metadata.patterns_included.len());\n}\n\n/// Test error recovery and fallback systems\n#[tokio::test]\nasync fn test_error_recovery_system() {\n    let recovery_system = ErrorRecoverySystem::new();\n    \n    // Test fallback access\n    let fallback_access = recovery_system.get_fallback_access();\n    assert!(fallback_access.is_ok(), \"Fallback access should be available\");\n    \n    let fallback = fallback_access.unwrap();\n    \n    // Test fallback functionality\n    let pattern = fallback.get_pattern(\"god_object\");\n    assert!(pattern.is_some(), \"Fallback should provide essential patterns\");\n    \n    let patterns = fallback.search_patterns(\"object\");\n    assert!(!patterns.is_empty(), \"Fallback search should work\");\n    \n    // Test recovery statistics\n    let stats = recovery_system.get_recovery_statistics();\n    assert_eq!(stats.total_errors, 0, \"No errors should be recorded yet\");\n    assert_eq!(stats.success_rate, 1.0, \"Success rate should be perfect initially\");\n    \n    println!(\"✅ Error recovery system initialized successfully\");\n    println!(\"   Fallback patterns available: {}\", fallback.get_statistics().available_patterns);\n}\n\n/// Test performance monitoring system\n#[tokio::test]\nasync fn test_performance_monitoring() {\n    let monitor = KnowledgePerformanceMonitor::new(false); // Disable profiling for test\n    let metrics = monitor.get_metrics();\n    \n    // Simulate some operations\n    for i in 0..100 {\n        let duration_ns = (i * 1000) as u64; // Simulate varying lookup times\n        monitor.record_lookup(&format!(\"pattern_{}\", i % 10), duration_ns);\n    }\n    \n    // Generate performance report\n    let report = monitor.generate_report();\n    \n    // Validate report structure\n    assert!(report.summary.overall_score > 0.0, \"Performance score should be calculated\");\n    assert!(!report.optimization_suggestions.is_empty() || report.summary.overall_score > 90.0, \n           \"Should have suggestions or high score\");\n    \n    // Validate metrics\n    assert!(report.metrics.throughput_ops_sec > 0.0, \"Throughput should be calculated\");\n    \n    println!(\"✅ Performance monitoring system functional\");\n    println!(\"   Overall score: {:.2}\", report.summary.overall_score);\n    println!(\"   Performance grade: {:?}\", report.summary.performance_grade);\n    println!(\"   Optimization suggestions: {}\", report.optimization_suggestions.len());\n}\n\n/// Test configuration management\n#[tokio::test]\nasync fn test_configuration_management() {\n    let config = KnowledgeInfrastructureConfig::default();\n    let config_manager = ConfigurationManager::new(config);\n    \n    // Test configuration updates\n    let result = config_manager.update_config(\"performance\", |config| {\n        config.performance.target_load_time_ms = 50;\n        config.performance.max_memory_usage_mb = 80;\n    });\n    \n    assert!(result.is_ok(), \"Configuration update should succeed\");\n    \n    // Validate updated configuration\n    let updated_config = config_manager.get_config();\n    assert_eq!(updated_config.performance.target_load_time_ms, 50);\n    assert_eq!(updated_config.performance.max_memory_usage_mb, 80);\n    \n    // Test invalid configuration rejection\n    let invalid_result = config_manager.update_config(\"performance\", |config| {\n        config.performance.target_load_time_ms = 0; // Invalid\n    });\n    \n    assert!(invalid_result.is_err(), \"Invalid configuration should be rejected\");\n    \n    println!(\"✅ Configuration management working correctly\");\n}\n\n/// Test system integration under load\n#[tokio::test]\nasync fn test_system_integration_under_load() {\n    // Initialize full system\n    let config = KnowledgeInfrastructureConfig::default();\n    let loader = KnowledgeLibraryLoader::embedded();\n    let lookup = Arc::new(loader.load_knowledge_library().await.unwrap());\n    let performance_metrics = Arc::new(PerformanceMetrics::new());\n    \n    let concurrent_access = Arc::new(ConcurrentKnowledgeAccess::new(\n        lookup, performance_metrics.clone(), 1000, 100\n    ));\n    \n    let monitor = KnowledgePerformanceMonitor::new(false);\n    let recovery_system = ErrorRecoverySystem::new();\n    let config_manager = ConfigurationManager::new(config);\n    \n    // Simulate sustained load\n    let load_duration = Duration::from_secs(5);\n    let start_time = Instant::now();\n    let mut handles = Vec::new();\n    \n    // Spawn multiple concurrent tasks\n    for task_id in 0..10 {\n        let access = Arc::clone(&concurrent_access);\n        let monitor_clone = monitor.clone();\n        \n        let handle = tokio::spawn(async move {\n            let mut operations = 0;\n            let patterns = vec![\"god_object\", \"magic_numbers\"];\n            \n            while start_time.elapsed() < load_duration {\n                for pattern_id in &patterns {\n                    let op_start = Instant::now();\n                    \n                    match timeout(\n                        Duration::from_millis(100),\n                        access.get_pattern_concurrent(pattern_id)\n                    ).await {\n                        Ok(Ok(_)) => {\n                            let duration = op_start.elapsed();\n                            monitor_clone.record_lookup(pattern_id, duration.as_nanos() as u64);\n                            operations += 1;\n                        }\n                        Ok(Err(e)) => {\n                            eprintln!(\"Task {} operation failed: {}\", task_id, e);\n                        }\n                        Err(_) => {\n                            eprintln!(\"Task {} operation timed out\", task_id);\n                        }\n                    }\n                }\n                \n                // Small delay to prevent overwhelming the system\n                tokio::time::sleep(Duration::from_millis(1)).await;\n            }\n            \n            operations\n        });\n        \n        handles.push(handle);\n    }\n    \n    // Wait for all tasks\n    let results = futures::future::join_all(handles).await;\n    let total_operations: usize = results.iter().map(|r| r.unwrap()).sum();\n    let total_duration = start_time.elapsed();\n    \n    // Calculate system metrics\n    let throughput = total_operations as f64 / total_duration.as_secs_f64();\n    let stats = concurrent_access.get_access_statistics();\n    let health = concurrent_access.health_check();\n    \n    // Validate system performed well under load\n    assert!(throughput > 500.0, \"System should maintain >500 ops/sec under load\");\n    assert!(stats.success_rate > 0.95, \"Success rate should be >95% under load\");\n    assert!(\n        matches!(health.status, concurrent::HealthStatus::Healthy | concurrent::HealthStatus::Degraded),\n        \"System should remain healthy or degraded (not unhealthy) under load\"\n    );\n    \n    println!(\"✅ System integration under load test passed\");\n    println!(\"   Total operations: {}\", total_operations);\n    println!(\"   Throughput: {:.2} ops/sec\", throughput);\n    println!(\"   Success rate: {:.2}%\", stats.success_rate * 100.0);\n    println!(\"   Health status: {:?}\", health.status);\n    println!(\"   Cache hit rate: {:.2}%\", stats.cache_hit_rate * 100.0);\n}\n\n/// Test comprehensive system validation\n#[tokio::test]\nasync fn test_comprehensive_system_validation() {\n    println!(\"🚀 Starting comprehensive system validation...\");\n    \n    // Run all individual tests to ensure they pass\n    test_loading_performance_targets().await;\n    test_lookup_performance_targets().await;\n    test_memory_usage_targets().await;\n    test_concurrent_access_performance().await;\n    test_ai_integration_performance().await;\n    test_error_recovery_system().await;\n    test_performance_monitoring().await;\n    test_configuration_management().await;\n    test_system_integration_under_load().await;\n    \n    println!(\"🎉 All system validation tests passed!\");\n    println!(\"\");\n    println!(\"📊 Performance Summary:\");\n    println!(\"   ✅ Loading time: <100ms\");\n    println!(\"   ✅ Lookup time: <1ms\");\n    println!(\"   ✅ Memory usage: <100MB\");\n    println!(\"   ✅ Throughput: >1000 ops/sec\");\n    println!(\"   ✅ Concurrent access: Thread-safe\");\n    println!(\"   ✅ AI integration: Functional\");\n    println!(\"   ✅ Error recovery: Resilient\");\n    println!(\"   ✅ Configuration: Manageable\");\n    println!(\"   ✅ System integration: Stable under load\");\n    println!(\"\");\n    println!(\"🚀 Knowledge library infrastructure is production-ready!\");\n}\n"